/** A level is open once the previous one has been beaten (at least 1 star). */
export function isLevelUnlocked(index: number, stars: Record<string, number>): boolean {
  if (index <= 0) return true;
  const prev = LEVELS[index - 1];
  return !!prev && (stars[prev.id] ?? 0) > 0;
}

export function totalStars(stars: Record<string, number>): number {
  return LEVELS.reduce((n, l) => n + (stars[l.id] ?? 0), 0);
}

export interface RegionDef {
  name: string;
  first: number; // index of the first level in this region
  count: number; // levels planned for the region (some may not exist yet)
  snow?: boolean;
  ember?: boolean;
  dusk?: boolean;
  shoal?: boolean;
  glass?: boolean;
  gale?: boolean;
  ruins?: boolean;
  gears?: boolean;
  abyss?: boolean;
  orchard?: boolean;
  storm?: boolean;
  dunes?: boolean;
  reef?: boolean;
  flotilla?: boolean;
  amber?: boolean;
  mist?: boolean;
  canopy?: boolean;
  comb?: boolean;
  bog?: boolean;
  thistle?: boolean;
  wold?: boolean;
  canyon?: boolean;
  brook?: boolean;
}

export const REGIONS: RegionDef[] = [
  { name: 'The Grovelands', first: 0, count: 5 },
  { name: 'Frostfern Highlands', first: 5, count: 5, snow: true },
  { name: 'The Emberdeep', first: 10, count: 5, ember: true },
  { name: 'The Duskcap Weald', first: 15, count: 5, dusk: true },
  { name: 'The Saltmarrow Shoals', first: 20, count: 5, shoal: true },
  { name: 'The Shardglass Barrens', first: 25, count: 5, glass: true },
  { name: 'The Galecrest Aeries', first: 30, count: 5, gale: true },
  { name: 'The Verdant Ruins', first: 35, count: 5, ruins: true },
  { name: 'The Brasswork Hollows', first: 40, count: 5, gears: true },
  { name: 'The Starwell Abyss', first: 45, count: 5, abyss: true },
  { name: 'The Rotbloom Orchard', first: 50, count: 5, orchard: true },
  { name: 'The Thunderhead Steppes', first: 55, count: 5, storm: true },
  { name: 'The Sunscour Dunes', first: 60, count: 5, dunes: true },
  { name: 'The Coralreach Shallows', first: 65, count: 5, reef: true },
  { name: 'The Blackwake Flotilla', first: 70, count: 5, flotilla: true },
  { name: 'The Amberwood', first: 75, count: 5, amber: true },
  { name: 'The Mistwreath Terraces', first: 80, count: 5, mist: true },
  { name: 'The Highcanopy', first: 85, count: 5, canopy: true },
  { name: 'The Honeycomb Hills', first: 90, count: 5, comb: true },
  { name: 'The Glimmerbog', first: 95, count: 5, bog: true },
  { name: 'The Thistledown Prairie', first: 100, count: 5, thistle: true },
  { name: 'The Patchwork Wolds', first: 105, count: 5, wold: true },
  { name: 'The Rustrock Canyons', first: 110, count: 5, canyon: true },
  { name: 'The Pebblebrook Rapids', first: 115, count: 5, brook: true },
];

export function regionOf(levelIndex: number): number {
  for (let r = REGIONS.length - 1; r >= 0; r--) if (levelIndex >= REGIONS[r].first) return r;
  return 0;
}
